$chatId..read:
auth != null && (
                    (
                      data.child('type').val() === 'group' &&
                      data.child('members').child(auth.uid).exists()
                    ) ||
                    (
                      data.child('type').val() !== 'group' &&
                      (
                        data.child('participantA').val() === auth.uid ||
                        data.child('participantB').val() === auth.uid
                      )
                    )
                  )
